from copy import deepcopy
import math


def prepare_forecast(records, new_record, query, coefficient, offset):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    def validate_number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be numeric")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")

    def validate_record(record, name):
        if not isinstance(record, dict):
            raise TypeError(f"{name} must be a dictionary")
        if set(record) != {"signal", "result"}:
            raise ValueError(f"{name} must have exactly signal and result")
        validate_number(record["signal"], f"{name}.signal")
        validate_number(record["result"], f"{name}.result")

    for index, record in enumerate(records):
        validate_record(record, f"records[{index}]")
    if new_record is not None:
        validate_record(new_record, "new_record")
    validate_number(query, "query")
    validate_number(coefficient, "coefficient")
    validate_number(offset, "offset")

    copied_records = list(records)
    if new_record is not None:
        copied_records.append(deepcopy(new_record))
    return {
        "records": copied_records,
        "forecast": float(coefficient * query + offset),
    }

